{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles Rent Stabilization Ordinance rent increase limits","requirement":"Rent for RSO-covered units may be increased only once every 12 months by the allowable rent increase percentage. Since February 2, 2026, no additional utility percentage increase and no 10% increase for an added dependent are allowed.","key_value":"allowable rent increase percentage once every 12 months","coverage_conditions":"Rental properties first built on or before October 1, 1978, and replacement units under LAMC Section 151.28, including apartments, condominiums, townhomes, duplexes, ADUs and mobile homes in mobile home parks.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":"Condominium and townhome rent amounts are not regulated for tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28 and if any of the following:"]},"exemptions":"Condominium and townhome tenancies commenced after December 31, 1995 are not rent-regulated; a landlord may apply for a luxury exemption based on the monthly rent charged on or before May 31, 1978.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Rent Stabilization Ordinance legal reasons for eviction","requirement":"A landlord of an RSO unit may end a tenancy only for listed at-fault or no-fault reasons, must file every termination notice with LAHD within three business days of service, and must pay relocation assistance for no-fault evictions.","key_value":null,"coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance, generally those first built on or before October 1, 1978.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28 and if any of the following:"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"L.A.M.C. § 151.09","quoted_span":"Tenant is at-fault\nFailure to pay rent\nFailure to fix or address a violation of the rental agreement","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","n_rules":2,"note":null}

